import type { StatId } from '../core/unit-stats';
import type { ResourceBundle, ResourceId } from '../core/resources';

/** Exact factual tables from revision 22193; never automatic runtime overrides. */
export const SPECIES_STATS_SOURCE = 'https://the-official-worldbox-wiki.fandom.com/wiki/Creature_Genomes_and_Stats?oldid=22193';
export const GENOME_BUDGET_KEYS = ['health', 'stamina', 'damage', 'armor', 'speed', 'diplomacy', 'warfare', 'stewardship', 'intelligence', 'lifespan', 'offspring', 'birth-rate', 'random-sex', 'mutagenic', 'harmful'] as const;
export type GenomeBudgetKey = typeof GENOME_BUDGET_KEYS[number];
/** null = absent contribution; 0 = explicit numeric zero. */
export type GenomeBudget = Partial<Record<GenomeBudgetKey, number | null>>;
export type SpeciesBaseStats = Partial<Record<StatId | 'baseMass' | 'massStat' | 'knockback' | 'areaOfEffect' | 'throwingRange' | 'supplyTimer', number | null>>;
export interface SourceGenome { id: string; name: string; budget: GenomeBudget }
export interface SourceBase { id: string; name: string; stats: SpeciesBaseStats }
export interface SourceSpecial {
  id: string; name: string; mass: number | string | null; cities: number | null; chromosome: string | null;
  color: string | null; zombieColor: string | null; baseDrops: ResourceBundle | null;
  /** Production is not permission to eat; the source has no diet table. */
  produces: ResourceId[]; diet: null;
}
function freeze<T>(value: T): T {
  if (value && typeof value === 'object') { for (const child of Object.values(value)) freeze(child); Object.freeze(value); }
  return value;
}
export const SOURCE_COMMON_BASE: SpeciesBaseStats = freeze({ attackSpeed: 1, accuracy: 1, knockback: 1.5, targets: 1, range: 1, criticalMultiplier: 2, areaOfEffect: 0.1, throwingRange: 7, supplyTimer: 1 });
export const SOURCE_COMMON_EXCEPTIONS: Readonly<Record<string, SpeciesBaseStats>> = freeze({
  'living-plant': { attackSpeed: 70, knockback: 1.2, targets: 3 }, 'living-house': { attackSpeed: 60, knockback: 1.4, targets: 3 },
  'boat-trading': { attackSpeed: 0.1 }, 'boat-transport': { attackSpeed: 0.5 }, 'arrow-shooting-boats': { accuracy: 4 },
  'cannonball-shooting-boats': { areaOfEffect: 3 }, 'watch-towers': { areaOfEffect: 1 },
  dragon: { attackSpeed: null, knockback: null, targets: 20, accuracy: null, range: null, criticalMultiplier: null, throwingRange: null, supplyTimer: null },
});
const withoutCommon = new Set(['ufo', 'crabzilla', 'god-finger', 'boats']);
const aliases: Record<string, string> = { boat: 'boats', 'mush-humanoid': 'mush', 'mush-animal': 'mush',
  'tumor-monster-humanoid': 'tumor-monster', 'tumor-monster-animal': 'tumor-monster',
  'blue-langton-ant': 'langton-and-printer-ants', 'green-langton-ant': 'langton-and-printer-ants',
  'black-langton-ant': 'langton-and-printer-ants', 'red-langton-ant': 'langton-and-printer-ants', printer: 'langton-and-printer-ants' };
export function referenceId(speciesId: string): string { return speciesId.startsWith('fire-elemental-') ? 'fire-elemental' : aliases[speciesId] ?? speciesId; }
export function speciesReference(speciesId: string) {
  const id = referenceId(speciesId), genome = SOURCE_GENOMES.find(g => g.id === id);
  if (!genome) return;
  const bases = SOURCE_BASES.filter(b => b.id === id || b.id === speciesId || b.id.startsWith(`${id}-`)
    || id === 'boats' && b.id.startsWith('boat-') || id === 'langton-and-printer-ants' && ['langton-ants', 'printer'].includes(b.id));
  const special = SOURCE_SPECIALS.filter(p => p.id === id || id === 'langton-and-printer-ants' && p.id.endsWith('-ant'));
  const common = withoutCommon.has(id) ? { areaOfEffect: 0.1 } : { ...SOURCE_COMMON_BASE, ...SOURCE_COMMON_EXCEPTIONS[id] };
  const commonExceptions = id === 'boats' ? Object.fromEntries(Object.entries(SOURCE_COMMON_EXCEPTIONS).filter(([key]) => key.includes('boat')))
    : SOURCE_COMMON_EXCEPTIONS[id] ? { [id]: SOURCE_COMMON_EXCEPTIONS[id] } : {};
  return { source: SPECIES_STATS_SOURCE, genome, bases, common, commonExceptions, special,
    inheritance: ['bioblob', 'lil-pumpkin', 'assimilator'].includes(id) ? 'tumor-monster' : null,
    notes: id === 'navy-seal' ? ['mass-conflict'] : id === 'zombie' ? ['inherits-body'] : id === 'ghost' || id.startsWith('living-') ? ['genome-capabilities-differ'] : [] };
}
/** Add inherited sources once, before placement; never add this budget again to the finished stats. */
export function referenceGenomeBudget(speciesId: string, animalCivil = false): GenomeBudget | null {
  const reference = speciesReference(speciesId);
  if (!reference || Object.values(reference.genome.budget).every(n => n === null)) return null;
  const result = { ...reference.genome.budget };
  if (reference.inheritance) for (const [key, n] of Object.entries(SOURCE_GENOMES.find(g => g.id === reference.inheritance)!.budget)) {
    if (n !== null) result[key as GenomeBudgetKey] = (result[key as GenomeBudgetKey] ?? 0) + n;
  }
  if (animalCivil) for (const key of ['diplomacy', 'warfare', 'stewardship', 'intelligence'] as const) result[key] = (result[key] ?? 0) + 3;
  return result;
}
